WITH f AS (SELECT PGM_SYS_ID, STATE FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FACILITIES WHERE AIR_POLLUTANT_CLASS_CODE='MAJ' AND AIR_OPERATING_STATUS_CODE='OPR' AND STATE IN ('IA','IN','NE','IL','MN','WI','MO')),
v AS (SELECT f.STATE, COUNT(*) VIOL, COUNT(HPV_DAYZERO_DATE) HPV FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_VIOLATION_HISTORY x JOIN f USING(PGM_SYS_ID) WHERE COALESCE(HPV_DAYZERO_DATE,EARLIEST_FRV_DETERM_DATE) BETWEEN '2015-01-01' AND '2025-12-31' GROUP BY 1),
fa AS (SELECT f.STATE, COUNT_IF(STATE_EPA_FLAG='S') FA_STATE, COUNT_IF(STATE_EPA_FLAG='E') FA_EPA, COUNT(DISTINCT IFF(STATE_EPA_FLAG='S',PGM_SYS_ID,NULL)) FAC_W_STATE_FA FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FORMAL_ACTIONS x JOIN f USING(PGM_SYS_ID) WHERE SETTLEMENT_ENTERED_DATE BETWEEN '2015-01-01' AND '2025-12-31' GROUP BY 1),
st AS (SELECT f.STATE, COUNT_IF(AIR_STACK_TEST_STATUS_CODE='FAI') FAI_ROWS, COUNT_IF(AIR_STACK_TEST_STATUS_CODE='PSS') PSS_ROWS, COUNT_IF(AIR_STACK_TEST_STATUS_CODE NOT IN ('FAI','PSS') OR AIR_STACK_TEST_STATUS_CODE IS NULL) OTHER_ROWS, LISTAGG(DISTINCT AIR_STACK_TEST_STATUS_CODE,',') CODES, COUNT(DISTINCT PGM_SYS_ID) FAC_TESTED FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_STACK_TESTS x JOIN f USING(PGM_SYS_ID) WHERE ACTUAL_END_DATE BETWEEN '2015-01-01' AND '2025-12-31' GROUP BY 1),
n AS (SELECT STATE, COUNT(*) N_MAJ FROM f GROUP BY 1)
SELECT * FROM n LEFT JOIN v USING(STATE) LEFT JOIN fa USING(STATE) LEFT JOIN st USING(STATE) ORDER BY 1
